// ============================================================
// פונקציות מנה ושורש — the eight STAGES of the study track
// ============================================================
//
// Authored 2026-08-29 to the owner's own eight-level spec for the
// `functions-rational-root` topic of paper-571, in the same shape the
// סדרות / הסתברות / גאומטריה tracks already use: dedicated STAGE sub-topics
// in their own file, spread into the parent Lesson (math5Functions) so
// `getSubTopics` / `resolveRoadmapNode` find them, while the generic
// פונקציות modules keep serving the quiz + reference banks untouched.
//
//   rq-domain           רמה 1  what a domain IS, when you even have to check
//                              one, and how the condition is SOLVED — including
//                              a quadratic under the root, via the parabola
//   rq-intersections    רמה 2  axis intersections: y=0 for the x-axis, x=0 for
//                              the y-axis, and what that means for a quotient
//                              (numerator zero) and a root (radicand zero)
//   rq-asymptotes       רמה 3  vertical, horizontal by DEGREE comparison, hole
//   rq-derivative       רמה 4  every derivative rule + composite ("times the
//                              inner derivative"), the derivative AS the slope
//                              of the tangent, extremum from f'=0, rise/fall
//                              by table and by second derivative
//   rq-sketch           רמה 5  turning the findings into an actual graph
//   rq-transformations  רמה 6  shifts, |f(x)|, stretches, even/odd, and the
//                              bagrut "thinking" clauses built on them
//   rq-integral         רמה 7  integration formulas, spotting an integral by
//                              its inner derivative, and the AREA procedure
//   rq-bagrut           רמה 8  full bagrut questions mixing all of the above
//
// House rules obeyed here (each one is a correction the owner already made on
// סדרות / הסתברות — do not regress them):
//   * every solution's steps[0] is '**הכלל:** <formula> — <trigger in the
//     question's own wording>', never leaking the final answer;
//   * naming a formula and substituting into it are two lines
//     ('**הנוסחה:**' then '**ההצבה:**'), one idea per step;
//   * no Hebrew inside $…$; no maqaf glued to a math island; no em-dash
//     touching math (both read as a minus sign in RTL);
//   * תיכון notation only;
//   * the term "כלל השרשרת" is never used — a composite function is derived
//     "כפול הנגזרת הפנימית", which is what the owner's students are taught;
//   * MCQ: correct option first (shuffled at render), every distractor is a
//     real misconception with a note that also points back at the right answer.

import type { StaticBagrutQuestion, SubTopic } from '../types';

