        teach: `בסוף כל שאלת חקירה מגיע הסעיף "שרטט סקיצה של הפונקציה". הוא נראה מפחיד, אבל הוא למעשה הסעיף ה**קל** ביותר, בתנאי אחד: שפתרת נכון את הסעיפים שלפניו.

### למה הוא אחרון

כי הוא לא מבקש שום דבר חדש. כל מה שצריך כבר נמצא:

| מה מצאנו | באיזו רמה | מה זה נותן בשרטוט |
|---|---|---|
| תחום הגדרה | רמה 1 | איפה בכלל יש גרף |
| חיתוכים עם הצירים | רמה 2 | נקודות ודאיות על הצירים |
| אסימפטוטות | רמה 3 | הגדרות שהגרף נצמד אליהן |
| קיצון, עלייה וירידה | רמה 4 | הצורה של כל ענף |

### מה זו "סקיצה"

**סקיצה אינה גרף מדויק.** לא צריך סרגל, לא צריך להציב עשרים נקודות, ולא צריך שהמידות יהיו לפי קנה מידה מדויק.

מה שכן חייב להיות נכון:

- מספר הענפים ומיקומם ביחס לאסימפטוטות.
- הכיוון של כל ענף, כלומר איפה עולה ואיפה יורדת.
- הסדר של הנקודות משמאל לימין.
- שהגרף אכן עובר דרך הנקודות שחישבת.

### המשפט שכדאי לזכור

הסקיצה היא **הסיכום** של השאלה, לא חישוב נוסף שלה. אם היא לא מסתדרת עם מה שחישבת, סימן שיש טעות באחד הסעיפים הקודמים, וזו הזדמנות מצוינת לתפוס אותה.`,
